```javascript
const {
    EmbedBuilder,
    ActionRowBuilder,
    ButtonBuilder,
    ButtonStyle,
    ChannelType,
    ComponentType
} = require('discord.js');
const PaymentProcessor = require('../structures/PaymentProcessor');
const crypto = require('crypto');
const { Cart, Payment } = require('../database/models/Models');

/**
 * @typedef {import('discord.js').Client} DiscordClient
 * @typedef {import('discord.js').Interaction} DiscordInteraction
 * @typedef {import('discord.js').GuildChannel} GuildChannel
 */

// --- CONSTANTES DE CONFIGURAÇÃO ---
const LOG_CHANNEL_ID = '1264758034979360860'; // <-- RECOMENDADO: Usar variáveis de ambiente
const CARGO_ID_ACCESS = '995154994183548953'; // <-- RECOMENDADO: Usar variáveis de ambiente
const INACTIVITY_DELAY_MS = 1000 * 60 * 5; // 5 minutos

/**
 * Gerencia o ciclo de vida do carrinho de compras de um usuário.
 * @class CartClass
 */
class CartClass {
    /**
     * Cria uma instância de CartClass
     * @param {DiscordClient} client O cliente do Discord.
     * @param {DiscordInteraction} interaction A interação inicial que disparou o carrinho.
     * @param {string} productId O ID do produto sendo comprado.
     * @param {Object} productData Dados do produto.
     * @param {string} [userId] O ID do usuário.
     */
    constructor(client, interaction, productId, productData, userId) {
        this.client = client;
        this.interaction = interaction;
        this.productId = productId;
        this.productData = productData;
        this.user = userId ? this.client.users.cache.get(userId) : interaction?.user;

        if (!this.user) {
            throw new Error("Usuário não encontrado para iniciar o carrinho.");
        }

        this.paymentProcessor = new PaymentProcessor();
        this.inactivityTimer = null;
        this.cartId = crypto.randomBytes(10).toString('hex');
        this.channel = null; // Thread ou Channel onde o carrinho está
        this.quantity = 1;
        this.selectedPlan = null;
        this.days = 0; // Dias de validade do plano
        this.message = null; // Message object no canal do carrinho
        this.paymentId = null; // ID do pagamento gerado

        // Configuração inicial de inatividade
        this.inactivityDelay = INACTIVITY_DELAY_MS;
    }

    /**
     * Envia um log para o canal de logs configurado.
     * @param {EmbedBuilder} embed O embed do log a ser enviado.
     */
    async sendLog(embed) {
        if (!LOG_CHANNEL_ID) {
            console.warn("Configuração do canal de logs ausente.");
            return;
        }
        const logChannel = this.client.channels.cache.get(LOG_CHANNEL_ID);
        if (logChannel && logChannel.isTextBased()) {
            try {
                await logChannel.send({ embeds: [embed] });
            } catch (error) {
                console.error("Falha ao enviar log:", error);
            }
        }
    }

    /**
     * Cria a embed de encerramento por inatividade.
     * @returns {EmbedBuilder} A embed de notificação de encerramento.
     */
    createInactivityEmbed() {
        return new EmbedBuilder()
            .setColor('#FF0000')
            .setDescription(`### 🙁 Seu carrinho foi encerrado\nOlá ${this.user.tag},\n\nSeu carrinho foi cancelado devido à inatividade, mas, você pode retomar sua compra a qualquer momento. Esperamos vê-lo novamente em breve. \n\n-# Atenciosamente, Nyox Applications.`)
            .setFooter({ text: `Carrinho ID: ${this.cartId}` });
    }

    /**
     * Cria a resposta para carrinho já existente.
     * @param {GuildChannel} channel O canal (thread) onde o carrinho existe.
     * @returns {{content: string, ephemeral: boolean, components: ActionRowBuilder[]}} Resposta do Discord.
     */
    createCartOpenEmbed(channel) {
        return {
            content: `✅ Você já tem um carrinho ativo!`,
            ephemeral: true,
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setStyle(ButtonStyle.Link)
                        .setLabel("Acessar Carrinho")
                        .setURL(channel.url)
                )
            ]
        };
    }

    /**
     * Cria a embed de sucesso ao abrir/retomar o carrinho.
     * @param {string} channelURL A URL do canal de carrinho.
     * @returns {{content: string, embeds: EmbedBuilder[], components: ActionRowBuilder[]}} Resposta do Discord.
     */
    createCartSuccessEmbed(channelURL) {
        return {
            content: "",
            embeds: [
                new EmbedBuilder()
                    .setColor('#060A18')
                    .setDescription(`### Olá, ${this.user.tag}, seu carrinho foi reaberto!\n\`🌟\` Você está prestes a adquirir o **${this.productData.productName}**, um sistema exclusivo da **Nyox Applications** com a melhor qualidade do mercado.\n-# Para continuar, clique no botão abaixo.`)
            ],
            components: [
                new ActionRowBuilder().addComponents(
                    new ButtonBuilder()
                        .setLabel("Acessar Carrinho")
                        .setStyle(ButtonStyle.Link)
                        .setEmoji("🛒")
                        .setURL(channelURL)
                )
            ]
        };
    }

    /**
     * Cria a embed de seleção de plano.
     * @returns {{content: string, embeds: EmbedBuilder[], components: ActionRowBuilder[]}} Resposta do Discord.
     */
    createPlanSelectionEmbed() {
        const { preco } = this.productData;
        const planFields = [];

        // Mapeamento para garantir consistência entre os dados do produto e os botões
        const planDefinitions = [
            { key: 'mensal', label: "📅 Plano Mensal", days: 30 },
            { key: 'quizena', label: "🗓️ Plano Quinzenal", days: 15 },
            { key: 'semanal', label: "📆 Plano Semanal", days: 7 }
        ];

        for (const { key, label, days } of planDefinitions) {
            if (preco[key]?.onoff) {
                planFields.push({
                    name: label,
                    value: `**${days} dias** - R$${preco[key].preco.toFixed(2)}`,
                    inline: true
                });
            }
        }

        return {
            content: `${this.user} <@&${CARGO_ID_ACCESS}>`, // Usando constante para o cargo
            embeds: [
                new EmbedBuilder()
                    .setTitle("🛒 Sistema de Compras")
                    .setColor("#00BFFF")
                    .setAuthor({
                        name: this.client.user.username,
                        iconURL: this.client.user.displayAvatarURL({ dynamic: true })
                    })
                    .setDescription(`👋 Olá, ${this.user.username}! Escolha o plano desejado para finalizar sua compra.`)
                    .addFields(planFields)
            ],
            components: [this.createPlanButtons()]
        };
    }

    /**
     * Cria os botões de seleção de plano e cancelamento.
     * @returns {ActionRowBuilder} A linha de botões.
     */
    createPlanButtons() {
        const row = new ActionRowBuilder();
        const { preco } = this.productData;

        const planDefinitions = [
            { key: 'mensal', label: "30 Dias", emoji: "📅", customId: "30DiasCart" },
            { key: 'quizena', label: "15 Dias", emoji: "📅", customId: "15DiasCart" },
            { key: 'semanal', label: "7 Dias", emoji: "📅", customId: "7DiasCart" }
        ];

        for (const { key, label, emoji, customId } of planDefinitions) {
            if (preco[key]?.onoff) {
                row.addComponents(
                    new ButtonBuilder()
                        .setEmoji(emoji)
                        .setLabel(label)
                        .setStyle(ButtonStyle.Primary)
                        .setCustomId(customId)
                );
            }
        }

        row.addComponents(
            new ButtonBuilder()
                .setCustomId("cancelOrder")
                .setEmoji("❌")
                .setLabel("Cancelar Pedido")
                .setStyle(ButtonStyle.Danger)
        );

        return row;
    }

    /**
     * Define um timer para inatividade.
     * @param {function} callback Função a ser executada ao expirar o tempo.
     * @param {number} delay O tempo de espera em milissegundos.
     */
    setInactivityTimer(callback, delay) {
        if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
        this.inactivityTimer = setTimeout(callback, delay);
    }

    /**
     * Lida com o cancelamento por inatividade do usuário.
     */
    async handleInactivity() {
        try {
            // Envia mensagem privada ao usuário (pode falhar se o usuário bloqueou o bot)
            try {
                await this.user.send({
                    embeds: [this.createInactivityEmbed()],
                    components: [
                        new ActionRowBuilder().addComponents(
                            new ButtonBuilder()
                                .setCustomId("automaticMessage123")
                                .setLabel("Mensagem Automatica")
                                .setStyle(ButtonStyle.Secondary)
                                .setDisabled(true)
                        )
                    ]
                });
            } catch (e) {
                console.warn(`Não foi possível enviar mensagem privada para ${this.user.tag} (pode ter bloqueado o bot).`);
            }

            // Cria e envia log
            const logEmbed = new EmbedBuilder()
                .setTitle("🔒 Carrinho Encerrado por Inatividade")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild?.name || 'Sistema', iconURL: this.interaction.guild?.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 | Usuário:', value: `${this.user.username} - \`${this.user.id}\``, inline: false },
                    { name: '📝 | Carrinho ID:', value: `Produto: ${this.productData.productName} - \`${this.cartId}\``, inline: false },
                    { name: '🕒 | Data / Horário do Fechamento:', value: new Date().toLocaleString(), inline: false },
                    { name: '❔ | Motivo:', value: `Inatividade (${(this.inactivityDelay / 60000)} minutos)` }
                );

            await this.sendLog(logEmbed);

            // Limpeza do canal e do banco de dados
            if (this.channel) {
                try {
                    await this.channel.delete();
                    await Cart.deleteOne({ channelId: this.channel.id });
                } catch (error) {
                    console.error("Erro ao limpar canal/DB após inatividade:", error);
                }
            }
        } catch (error) {
            console.error("ERRO FATAL ao lidar com inatividade:", error);
        }
    }

    /**
     * Lida com a criação e processamento do pagamento.
     * @param {Object} paymentResponse Retorno da API de pagamento.
     */
    async processPayment(paymentResponse) {
        try {
            if (!paymentResponse || !paymentResponse.id) {
                throw new Error("Resposta de pagamento inválida ou incompleta.");
            }

            const { id, attachment, pixCopyPasteCode } = paymentResponse;
            console.log(`[Payment] - Pagamento criado com sucesso (${id})`);

            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);

            // 1. Atualiza a mensagem do carrinho para mostrar os detalhes do pagamento
            await this.message.edit({
                embeds: [
                    new EmbedBuilder()
                        .setTitle("🛒 Resumo Final do Pedido")
                        .setDescription(`### Finalizar Compra\n\`📨\` **ID Carrinho**: ${this.cartId}\n\`📦\` **Produto**: ${this.productData.productName}\n\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias\n\`💸\` **Total a Pagar**: R$${totalAmount.toFixed(2)}`)
                        .setColor('#FFD700')
                        .setFooter({ text: "Pagamento com Pix" }),

                    new EmbedBuilder()
                        .setDescription("- **Instruções de Pagamento**\n- Pague o Pix usando o QR Code ou o código abaixo.\n- O sistema fará a verificação automática.\n- **Importante:** O pagamento deve ser feito dentro do prazo de expiração do QR Code/Código. (Este timer é um placeholder.)")
                        .setImage(`attachment://qrcode.png`)
                        .setColor('#060A18')
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setCustomId("pixCopyPaste")
                            .setLabel("Código Copia e Cola")
                            .setEmoji("💰")
                            .setStyle(ButtonStyle.Secondary),
                        new ButtonBuilder()
                            .setCustomId("cancelPayment")
                            .setLabel("Cancelar Pedido")
                            .setStyle(ButtonStyle.Danger)
                    )
                ]
            });

            // 2. Envia o QR Code/Anexo principal
            if (attachment) {
                await this.channel.send({ files: [attachment] });
            }

            // 3. Monitoramento do Status do Pagamento
            const checkPaymentStatus = setInterval(async () => {
                try {
                    // *** SUBSTITUA PELO USO REAL DO PROCESSADOR ***
                    //const status = await this.paymentProcessor.checkPaymentStatus(id);
                    const status = 'approved'; // Simulação para teste

                    console.log(`[Payment] - Status do pagamento (${id}): ${status}`);

                    if (status === "approved") {
                        clearInterval(checkPaymentStatus);
                        await this.handleApprovedPayment(id);
                    } else if (status === "cancelled" || status === "expired") {
                        clearInterval(checkPaymentStatus);
                        await this.handleInactivity(); // Tratar como falha/cancelamento
                    }
                    // Ignora outros status (pending, etc.)
                } catch (error) {
                    console.error("Erro ao verificar status do pagamento:", error);
                    clearInterval(checkPaymentStatus); // Para evitar loops infinitos em caso de erro
                    await this.handleInactivity();
                }
            }, 60000); // Verifica a cada 60 segundos

        } catch (error) {
            console.error("ERRO crítico ao processar pagamento:", error);
            // Tenta notificar o usuário se a mensagem ainda estiver acessível
            if (this.message) {
                await this.message.edit({ content: `❌ Falha ao gerar detalhes do pagamento: ${error.message}. Por favor, entre em contato com o suporte.` });
            }
        }
    }

    /**
     * Lida com o pagamento aprovado (Concessão de acesso).
     * @param {string} paymentId O ID do pagamento confirmado.
     */
    async handleApprovedPayment(paymentId) {
        try {
            const cart = await Cart.findOne({ channelId: this.channel.id });
            if (!cart || cart.status !== "Aguardando...") {
                console.warn("Carrinho não encontrado ou já processado no momento da aprovação do pagamento.");
                return;
            }

            // 1. Atualiza o status e salva no DB
            cart.status = "Processando";
            cart.paymentId = paymentId;
            await cart.save();

            // 2. Concede o cargo
            if (CARGO_ID_ACCESS) {
                const member = this.interaction.guild.members.cache.get(this.user.id);
                if (member) {
                    await member.roles.add(CARGO_ID_ACCESS)
                        .catch(e => console.log(`[Cargo] Usuário ${this.user.tag} já possuía o cargo ou erro ao adicionar: ${e.message}`));
                }
            }

            // 3. Limpeza de Logs e Canal
            await this.channel.bulkDelete(50);
            await this.channel.send({
                content: `✅ **Pagamento Aprovado!** Seu acesso foi liberado.\n🆔 ID da Compra: ${this.cartId}`
            });

            // 4. Mensagem final para o usuário
            await this.channel.send({
                content: `${this.user}`,
                embeds: [
                    new EmbedBuilder()
                        .setTitle("🎉 Acesso Concedido!")
                        .setDescription(`**O pagamento foi aprovado com sucesso!** Seu acesso ao ${this.productData.productName} foi liberado.`)
                        .setColor('#00FF00')
                        .addFields(
                            { name: "ID da Compra", value: `\`${this.cartId}\``, inline: true },
                            { name: "Plano Contratado", value: `${this.capitalize(this.selectedPlan)} (${this.days * this.quantity} dias)`, inline: true }
                        )
                ],
                components: [
                    new ActionRowBuilder().addComponents(
                        new ButtonBuilder()
                            .setLabel("Portal Desenvolvedor")
                            .setEmoji("🤖")
                            .setStyle(ButtonStyle.Link)
                            .setURL("https://discord.com/developers/applications/"),
                        new ButtonBuilder()
                            .setLabel("Tutorial")
                            .setEmoji("🔗")
                            .setStyle(ButtonStyle.Link)
                            .setURL("https://docs.nyox.tech/tutorials/createapp")
                    )
                ]
            });

            // 5. Log de Sucesso
            const successLogEmbed = new EmbedBuilder()
                .setTitle("✅ Compra Concluída com Sucesso")
                .setColor('#00FF00')
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild?.name || 'Sistema', iconURL: this.interaction.guild?.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 | Usuário:', value: `${this.user.username} - \`${this.user.id}\``, inline: false },
                    { name: '📝 | Produto', value: `**${this.productData.productName}**`, inline: false },
                    { name: '💰 | Valor Total', value: `R$${Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2)}`, inline: false },
                    { name: '⏳ | Prazo', value: `${this.days * this.quantity} dias`, inline: false }
                );
            await this.sendLog(successLogEmbed);

        } catch (error) {
            console.error("ERRO ao finalizar pagamento aprovado:", error);
            // Tentar informar o usuário que algo deu errado na concessão de acesso
            if (this.message) {
                await this.message.edit({ content: `⚠️ Erro interno na concessão do serviço. Por favor, contate o suporte com o ID ${this.cartId}.` });
            }
        }
    }

    /**
     * Cria a mensagem inicial de resumo do carrinho antes do pagamento.
     * @returns {{embeds: EmbedBuilder[], components: ActionRowBuilder[]}} Estrutura da mensagem.
     */
    createCartItemsMessage() {
        const { preco } = this.productData;
        const total = Number(preco[this.selectedPlan].preco * this.quantity).toFixed(2);

        const embed = new EmbedBuilder()
            .setTitle("🛒 Resumo do Seu Carrinho")
            .setDescription(`### Olá, ${this.user.tag}! Sua seleção foi feita. Revise os detalhes antes de finalizar.\n\n`
                + `\`📦\` **Produto**: ${this.productData.productName}\n`
                + `\`✨\` **Plano**: ${this.capitalize(this.selectedPlan)} (x${this.quantity}) - ${this.days * this.quantity} dias\n`
                + `\`💰\` **Valor Total**: **R$${total.toFixed(2)}**`)
            .setColor("#060A18")
            .setFooter({ text: `ID Carrinho: ${this.cartId}` });

        const buttonsRow = new ActionRowBuilder().addComponents(
            new ButtonBuilder()
                .setCustomId("addToCart")
                .setLabel("➕ Adicionar Mais")
                .setStyle(ButtonStyle.Primary),
            new ButtonBuilder()
                .setCustomId("removeFromCart")
                .setLabel("➖ Diminuir")
                .setStyle(ButtonStyle.Secondary),
            new ButtonBuilder()
                .setCustomId("finalizePurchase")
                .setLabel("✅ Confirmar Pedido e Pagar")
                .setStyle(ButtonStyle.Success)
                .setEmoji("✅"),
            new ButtonBuilder()
                .setCustomId("cancelOrder")
                .setLabel("❌ Cancelar Pedido")
                .setStyle(ButtonStyle.Danger)
                .setEmoji("❌")
        );

        return { embeds: [embed], components: [buttonsRow] };
    }

    /**
     * Lida com a seleção de plano (botões da tela inicial).
     * @param {DiscordInteraction} interaction A interação do botão.
     * @param {string} [forcePlan] O plano forçado para testes/retomada.
     */
    async handlePlanSelection(interaction, forcePlan) {
        try {
            let selectedKey;
            // Determina o plano selecionado
            switch (forcePlan || interaction.customId) {
                case "7DiasCart":
                    selectedKey = "semanal";
                    this.days = 7;
                    break;
                case "15DiasCart":
                    selectedKey = "quizena";
                    this.days = 15;
                    break;
                case "30DiasCart":
                    selectedKey = "mensal";
                    this.days = 30;
                    break;
                default:
                    return;
            }
            this.selectedPlan = selectedKey;

            // 1. Atualiza o DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity, status: "Aguardando...", selectedPlan: this.selectedPlan },
                { new: true }
            );

            // 2. Atualiza a mensagem do carrinho com o plano escolhido
            await this.message.edit(this.createCartItemsMessage());

            // 3. Log de Criação/Atualização do Carrinho
            const logEmbed = new EmbedBuilder()
                .setTitle("📝 Novo Plano Selecionado")
                .setColor("#FF4500")
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild?.name || 'Sistema', iconURL: this.interaction.guild?.iconURL({ dynamic: true }) })
                .addFields(
                    { name: "👥 Usuário", value: `${this.user.username} - \`${this.user.id}\``, inline: false },
                    { name: "🛒 Carrinho ID", value: `Produto: **${this.productData.productName}** - \`${this.cartId}\``, inline: false },
                    { name: "🕒 Data/Hora", value: `<t:${Math.floor(Date.now() / 1000)}:f> (<t:${Math.floor(Date.now() / 1000)}:R>)`, inline: false },
                    { name: "⭐ Plano Escolhido", value: `**${this.capitalize(this.selectedPlan)}** (${this.days} dias)` }
                );

            await this.sendLog(logEmbed);

            // 4. Reinicia o timer de inatividade
            this.setInactivityTimer(() => this.handleInactivity(), this.inactivityDelay);
        } catch (error) {
            console.error("ERRO ao lidar com seleção de plano:", error);
        }
    }

    /**
     * Finaliza a compra, chama a API de pagamento e inicia o monitoramento.
     * @param {DiscordInteraction} interaction A interação que disparou a finalização.
     */
    async finalizePurchase(interaction) {
        try {
            clearTimeout(this.inactivityTimer);

            const totalAmount = Number(this.productData.preco[this.selectedPlan].preco * this.quantity).toFixed(2);

            // 1. Preparação dos dados de pagamento (Use os dados reais da sua API)
            const paymentOptions = {
                amount: totalAmount,
                description: `Compra - ${this.user.username}`,
                first_name: this.user.firstName || 'Cliente',
                email: this.user.email || 'paymentsinbox@nyox.tech',
                otherData: {
                    notification_url: "https://nyox.tech/api/notifications"
                }
            };

            // 2. Chamada ao Processador de Pagamento
            // ATENÇÃO: Substituí a linha de mock por uma chamada mais clara, mas mantenha a lógica real.
            const paymentResponse = await this.paymentProcessor.getPayment(92690421680); 
            // Se estiver usando o paymentProcessor.processPayment, use-o aqui.

            if (!paymentResponse) {
                throw new Error("Falha ao obter a resposta de pagamento da API.");
            }

            // 3. Registro no DB
            const payment = new Payment({
                payment_id: paymentResponse.id,
                transaction_amount: totalAmount,
                description: paymentOptions.description,
                customerId: this.user.id,
                email: paymentOptions.email
            });
            await payment.save();

            // 4. Atualiza o carrinho com o Payment ID
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { paymentId: paymentResponse.id },
                { new: true }
            );

            // 5. Inicia o processo de exibição do boleto e monitoramento
            await this.processPayment(paymentResponse);

        } catch (error) {
            console.error("ERRO ao finalizar pedido:", error);
            if (interaction.deferred || interaction.replied) {
                await interaction.followUp({ content: "🛑 Ocorreu um erro crítico ao processar seu pedido. Por favor, tente novamente ou entre em contato com o suporte.", ephemeral: true });
            } else {
                await interaction.reply({ content: "🛑 Ocorreu um erro crítico ao processar seu pedido. Por favor, tente novamente ou entre em contato com o suporte.", ephemeral: true });
            }
        }
    }

    /**
     * Atualiza a quantidade no carrinho (adicionar ou remover).
     * @param {DiscordInteraction} interaction A interação do botão.
     * @param {"add" | "remove"} action A ação a ser executada.
     */
    async updateCartQuantity(interaction, action) {
        try {
            let newQuantity = this.quantity;
            if (action === "add") {
                newQuantity += 1;
            } else if (action === "remove") {
                newQuantity -= 1;
                if (newQuantity < 1) {
                    newQuantity = 1; // Mantém no mínimo 1 se remover, ou você pode zerar e cancelar
                    await interaction.reply({ embeds: [new EmbedBuilder().setDescription("❌ | A quantidade mínima é 1.")], ephemeral: true });
                    return;
                }
            }

            this.quantity = newQuantity;

            // 1. Atualiza o DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                { quantity: this.quantity },
                { new: true }
            );

            // 2. Atualiza a mensagem na thread
            await interaction.update(this.createCartItemsMessage());

            // 3. Reinicia o timer de inatividade
            this.setInactivityTimer(() => this.handleInactivity(), this.inactivityDelay);
        } catch (error) {
            console.error("ERRO ao atualizar quantidade do carrinho:", error);
        }
    }

    /**
     * Lida com o cancelamento geral da ordem pelo usuário.
     * @param {DiscordInteraction} interaction A interação do botão de cancelar.
     */
    async handleCancellation(interaction) {
        try {
            // 1. Atualiza o DB para um estado cancelado (opcional, mas bom para logs)
            await Cart.findOneAndUpdate({ channelId: this.channel.id }, { status: "Cancelado" });

            // 2. Cria e envia log
            const logEmbed = new EmbedBuilder()
                .setTitle("🗑️ Carrinho Cancelado pelo Usuário")
                .setColor('#FFA500')
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild?.name || 'Sistema', iconURL: this.interaction.guild?.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 Usuário', value: `${this.user.username} - \`${this.user.id}\``, inline: false },
                    { name: '📝 Carrinho ID', value: `Produto: **${this.productData.productName}** - \`${this.cartId}\``, inline: false },
                    { name: '❔ Motivo', value: `Cancelamento explícito pelo usuário.` }
                );
            await this.sendLog(logEmbed);

            // 3. Limpeza
            if (this.channel) {
                await this.channel.delete();
            }

            // 4. Resposta ao usuário
            if (interaction.deferred || interaction.replied) {
                await interaction.editReply({ content: "🛒 Seu carrinho foi cancelado com sucesso.", components: [] });
            } else {
                await interaction.reply({ content: "🛒 Seu carrinho foi cancelado com sucesso.", components: [] });
            }

        } catch (error) {
            console.error("ERRO ao lidar com cancelamento:", error);
            if (interaction.deferred || interaction.replied) {
                 await interaction.editReply({ content: "❌ Houve um erro ao cancelar o carrinho.", components: [] });
            }
        }
    }

    /**
     * Lida com o cancelamento do pagamento.
     * @param {DiscordInteraction} interaction A interação do botão de cancelar pagamento.
     */
    async handleCancelPayment(interaction) {
        try {
            // 1. Log
            const logEmbed = new EmbedBuilder()
                .setTitle("💳 Pagamento Cancelado")
                .setColor('#FF6347')
                .setAuthor({ name: this.client.user.username, iconURL: this.client.user.displayAvatarURL({ dynamic: true }) })
                .setFooter({ text: this.interaction.guild?.name || 'Sistema', iconURL: this.interaction.guild?.iconURL({ dynamic: true }) })
                .addFields(
                    { name: '👥 Usuário', value: `${this.user.username} - \`${this.user.id}\``, inline: false },
                    { name: '📝 Carrinho ID', value: `Produto: **${this.productData.productName}** - \`${this.cartId}\``, inline: false },
                    { name: '❔ Motivo', value: `Pagamento desfeito pelo usuário.` }
                );
            await this.sendLog(logEmbed);

            // 2. Tentativa de cancelamento na API (Assumindo que paymentId existe e está armazenado)
            if (this.paymentId) {
                try {
                     await this.paymentProcessor.cancelPayment(this.paymentId);
                } catch (e) {
                    console.warn(`Não foi possível cancelar o pagamento ${this.paymentId} via API. Pode já ter sido processado.`);
                }
            }

            // 3. Limpeza
            if (this.channel) {
                await this.channel.delete();
                await Cart.deleteOne({ channelId: this.channel.id });
            }

            // 4. Resposta
            if (interaction.deferred || interaction.replied) {
                await interaction.editReply({ content: "💳 Pagamento e carrinho cancelados com sucesso.", components: [] });
            } else {
                await interaction.reply({ content: "💳 Pagamento e carrinho cancelados com sucesso.", components: [] });
            }

        } catch (error) {
            console.error("ERRO ao cancelar pagamento:", error);
            if (interaction.deferred || interaction.replied) {
                 await interaction.editReply({ content: "❌ Houve um erro ao cancelar o pagamento.", components: [] });
            }
        }
    }

    /**
     * Cria o carrinho e inicia o processo de fluxo de mensagens.
     */
    async createCart() {
        try {
            // 1. Verifica carrinho existente
            const existingCart = await Cart.findOne({ userId: this.user.id });
            if (existingCart) {
                const guildChannel = this.client.channels.cache.get(existingCart.channelId);
                if (guildChannel) {
                    this.channel = guildChannel;
                    this.cartId = existingCart.id;
                    this.quantity = existingCart.quantity || 1;
                    this.selectedPlan = existingCart.selectedPlan;
                    // Reconstruindo os dias com base no plano salvo
                    const planMap = { 'mensal': 30, 'quizena': 15, 'semanal': 7 };
                    this.days = planMap[this.selectedPlan] || 1; 

                    return this.interaction ? this.interaction.reply(this.createCartOpenEmbed(guildChannel)) : true;
                }
                // Se o canal não existe, trata como novo carrinho (cleanup)
                await Cart.deleteOne({ _id: existingCart._id });
            }

            // 2. Inicia novo carrinho (Thread)
            await this.interaction.reply({ content: "⏳ Aguarde um momento, estou configurando seu carrinho...", ephemeral: true });

            const thread = await this.interaction.channel.threads.create({
                name: `🛒・${this.user.username}・${this.user.id}`,
                topic: `Carrinho de Compras - ${this.productData.productName} - ${this.cartId}`,
                autoArchiveDuration: 60,
                type: ChannelType.PrivateThread,
                reason: "Criação de carrinho de compras",
                members: [this.user.id],
                permissionOverwrites: [
                    {
                        id: this.user.id,
                        allow: ["ViewChannel", "SendMessages"],
                        deny: ["ViewChannel"] // Ajuste: O usuário deve poder ver e enviar
                    },
                    {
                        id: this.interaction.guild.id,
                        deny: ["ViewChannel", "SendMessages"]
                    }
                ]
            });

            this.channel = thread;

            // 3. Salva no DB
            await Cart.findOneAndUpdate(
                { channelId: this.channel.id },
                {
                    userId: this.user.id,
                    quantity: this.quantity,
                    cartId: this.cartId,
                    productId: this.productId,
                    status: "Aguardando..."
                },
                { upsert: true, new: true }
            );

            // 4. Inicia o Timer de Inatividade
            this.setInactivityTimer(() => this.handleInactivity(), this.inactivityDelay);

            // 5. Confirmação e Envio da Interface de Plano
            await this.interaction.editReply(this.createCartSuccessEmbed(this.channel.url));

            const initialEmbed = this.createPlanSelectionEmbed();
            this.message = await this.channel.send(initialEmbed);

            // Chama o manipulador de plano, mas força um plano inicial para iniciar o fluxo (ou deixa nulo para esperar o clique)
            await this.handlePlanSelection(this.interaction, null);

        } catch (error) {
            console.error("ERRO ao criar carrinho:", error);
            if (this.interaction) {
                await this.interaction.followUp({ content: "❌ Desculpe, ocorreu um erro grave ao inicializar o carrinho. Tente novamente.", ephemeral: true });
            }
        }
    }

    /**
     * Executa o ciclo de vida do carrinho.
     * @param {boolean} start Flag para indicar se o ciclo deve ser iniciado.
     */
    async run(start) {
        if (start) {
            await this.createCart();
        }

        // Collector para interações dentro do carrinho (Timeout de 10 minutos)
        const collector = this.channel?.createMessageComponentCollector({ componentType: ComponentType.Button, time: 600000 }); 

        collector.on("collect", async (btnInteraction) => {
            // Garante que a interação veio do próprio usuário do carrinho
            if (btnInteraction.user.id !== this.user.id) {
                await btnInteraction.deferUpdate();
                return;
            }

            clearTimeout(this.inactivityTimer);

            // Reinicia o timer ao interagir
            this.setInactivityTimer(() => this.handleInactivity(), this.inactivityDelay);

            try {
                switch (btnInteraction.customId) {
                    case "7DiasCart":
                    case "15DiasCart":
                    case "30DiasCart":
                        await btnInteraction.deferUpdate();
                        await this.handlePlanSelection(btnInteraction);
                        break;

                    case "cancelOrder":
                        await this.handleCancellation(btnInteraction);
                        break;

                    case "addToCart":
                        await this.updateCartQuantity(btnInteraction, "add");
                        break;

                    case "removeFromCart":
                        await this.updateCartQuantity(btnInteraction, "remove");
                        break;

                    case "finalizePurchase":
                        await this.finalizePurchase(btnInteraction);
                        break;

                    case "pixCopyPaste":
                    case "qrCode":
                        // Lógica para enviar detalhes de pagamento
                        const payment = await Cart.findOne({ channelId: this.channel.id });
                        if (payment && payment.paymentId && this.paymentProcessor) {
                            const paymentDetails = await this.paymentProcessor.getPayment(payment.paymentId);
                            if (!paymentDetails) {
                                await btnInteraction.reply({ content: "Detalhes do pagamento não encontrados no sistema.", ephemeral: true });
                                return;
                            }
                            if (btnInteraction.customId === "qrCode" && paymentDetails.attachment) {
                                await btnInteraction.reply({ files: [paymentDetails.attachment], ephemeral: true });
                            } else if (btnInteraction.customId === "pixCopyPaste" && paymentDetails.pixCopyPasteCode) {
                                await btnInteraction.reply({ content: paymentDetails.pixCopyPasteCode, ephemeral: true });
                            }
                        } else {
                            await btnInteraction.reply({ content: "Pagamento não inicializado. Por favor, complete a seleção do plano.", ephemeral: true });
                        }
                        break;

                    case "cancelPayment":
                        await this.handleCancelPayment(btnInteraction);
                        break;

                    default:
                        console.log(`Custom ID desconhecido: ${btnInteraction.customId}`);
                }
            } catch (e) {
                console.error("Erro durante o processamento da interação do carrinho:", e);
                if (btnInteraction.deferred || btnInteraction.replied) {
                    await btnInteraction.followUp({ content: "⚠️ Desculpe, houve um erro ao processar esta ação no carrinho.", ephemeral: true });
                } else {
                    await btnInteraction.reply({ content: "⚠️ Desculpe, houve um erro ao processar esta ação no carrinho.", ephemeral: true });
                }
            }
        });

        collector.on("end", () => {
            console.log(`[Cart ${this.cartId}] Coletor de interações finalizado. Tempo expirado.`);
            if (this.inactivityTimer) clearTimeout(this.inactivityTimer);
            // Se o colecionador acabar, o carrinho deve ser limpo ou marcado como inativo.
            if (this.channel) {
                 this.handleInactivity();
            }
        });
    }

    /**
     * Helper para capitalizar strings (mantido).
     * @param {string} str 
     * @returns {string}
     */
    capitalize(str) {
        if (typeof str !== 'string' || !str) return '';
        return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
    }
}

module.exports = CartClass;
