    </style>
</head>
<body>
    <h1>Chat Seguro</h1>
    <div id="status">Conectando...</div>
    <div id="chatArea"></div>
    <input type="text" id="messageInput" placeholder="Digite sua mensagem...">
    <button id="sendButton" disabled>Enviar</button>

    <script>
        // ATENÇÃO: Mude 'ws://localhost:8080' para o endereço real do seu servidor Ratchet
        const ws = new WebSocket('ws://localhost:8080'); 
        const statusElement = document.getElementById('status');
        const chatArea = document.getElementById('chatArea');
        const messageInput = document.getElementById('messageInput');
        const sendButton = document.getElementById('sendButton');

        const SECRET_PASSWORD = 'senha123'; // Deve bater com a senha no ChatController.php

        // --- FUNÇÕES DE UI ---
        function displayMessage(sender, message, type = 'system') {
            const p = document.createElement('p');
            if (type === 'system') {
                p.innerHTML = `<em>[SISTEMA] ${message}</em>`;
            } else {
                p.innerHTML = `<strong>${sender}:</strong> ${message}`;
            }
            chatArea.appendChild(p);
            chatArea.scrollTop = chatArea.scrollHeight; // Rola para o final
        }

        // --- GESTÃO DO WEBSOCKET ---

        ws.onopen = () => {
            statusElement.textContent = 'Status: Conectado ao Servidor.';

            // 1. INICIAÇÃO DA AUTENTICAÇÃO (Simulando a "Janela")
            promptSenha();
        };

        ws.onmessage = (event) => {
            const data = JSON.parse(event.data);
            console.log("Mensagem do Servidor:", data);

            switch (data.type) {
                case 'auth_request':
                    // O servidor está pedindo autenticação
                    displayMessage('Servidor', 'Por favor, insira sua senha para entrar no chat.');
                    break;

                case 'auth_success':
                    statusElement.textContent = 'Status: Autenticado! Você pode conversar.';
                    sendButton.disabled = false;
                    displayMessage('Servidor', '✅ Autenticação bem-sucedida! Bem-vindo.');
                    break;

                case 'auth_failed':
                    statusElement.textContent = 'Status: FALHA NA AUTENTICAÇÃO.';
                    displayMessage('Servidor', '❌ Senha incorreta. Conexão encerrada.');
                    ws.close(); // Fecha a conexão se falhar
                    break;

                case 'not_authenticated':
                    displayMessage('Servidor', 'Você precisa se autenticar para enviar ou receber mensagens.');
                    break;

                default:
                    // Se for uma mensagem normal do chat
                    displayMessage(data.sender || 'Outro Usuário', data.message);
            }
        };

        ws.onclose = () => {
            statusElement.textContent = 'Status: Desconectado.';
            sendButton.disabled = true;
            messageInput.disabled = true;
            displayMessage('Sistema', 'Você foi desconectado do chat.');
        };

        ws.onerror = (error) => {
            statusElement.textContent = 'Status: Erro de Conexão.';
            console.error("Erro no WebSocket:", error);
        };

        // --- FUNÇÃO PARA PEDIR SENHA (A "JANELA") ---
        function promptSenha() {
            // Usamos um prompt padrão do navegador, que é o mais simples para este exemplo
            const password = prompt("🔒 Por favor, digite a senha para acessar o chat:");

            if (password) {
                sendAuthentication(password);
            } else {
                statusElement.textContent = 'Status: Desconectado (Senha não fornecida).';
                ws.close();
            }
        }

        // --- ENVIO DE DADOS ---

        function sendAuthentication(password) {
            const authMessage = JSON.stringify({
                type: "authenticate",
                password: password
            });
            ws.send(authMessage);
        }

        document.getElementById('sendButton').onclick = () => {
            const message = messageInput.value.trim();
            if (message && ws.readyState === WebSocket.OPEN) {
                const chatMessage = JSON.stringify({
                    type: "chat_message",
                    sender: "ClienteJS", // Identificador no frontend
                    message: message
                });
                ws.send(chatMessage);
                messageInput.value = '';
            }
        };

        messageInput.addEventListener("keypress", function(e) {
            if (e.key === "Enter") {
                document.getElementById('sendButton').click();
            }
        });

    </script>
</body>
</html>
```

### 🚀 Resumo da Implementação

1. **No PHP (Servidor)**: Você precisou modificar o `onMessage` para **esperar e validar** uma mensagem de tipo `"authenticate"` antes de permitir o tráfego normal de chat.
2. **No HTML/JavaScript (Cliente)**:
    * O `ws.onopen` detecta que a conexão com o servidor está estabelecida.
    * Ele chama a função `promptSenha()`.
    * `promptSenha()` usa o comando `prompt()` do navegador, que **exibe a caixa de diálogo de solicitação de senha**.
